using Full.NET.Data.Abstractions;

namespace Full.NET.Modules.Ai.Persistence;

/// <summary>组织信息只写 AI 表；分页和筛选在当前知识库及文档双层授权之后执行。</summary>
internal static class AiKnowledgeDirectorySql
{
    private const string Host = " AND knowledge.TenantId IS NULL";
    private const string Tenant = " AND knowledge.TenantId=@TenantId";
    private const string OwnerRoot = " FROM fn_ai_knowledge_base AS knowledge WHERE knowledge.Id=@KnowledgeBaseId AND knowledge.IsEnabled=1 AND knowledge.OwnerUserId=@OwnerUserId";
    private const string FolderRoot = " FROM fn_ai_knowledge_folder AS folder INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=folder.KnowledgeBaseId WHERE knowledge.Id=@KnowledgeBaseId AND knowledge.IsEnabled=1";
    // 复用知识库读边界，防止前置授权等待后关系撤销仍泄露文件夹名称。
    private static string FolderAccess(bool mysql, bool scoped)
    {
        var text = AiKnowledgeSql.ReadFor(mysql ? DatabaseProvider.MySql : DatabaseProvider.SqlServer, scoped).Text;
        return " AND EXISTS (SELECT 1" + text[text.IndexOf(" FROM ", StringComparison.Ordinal)..].Replace("Id = @Id", "Id = @KnowledgeBaseId", StringComparison.Ordinal) + ")";
    }
    private const string FolderColumns = "folder.Id,folder.KnowledgeBaseId,folder.ParentId,folder.Name,folder.Version";
    internal static readonly SqlStatement InsertFolderHost = new("ai.knowledge_directory.insert_folder_host", "INSERT INTO fn_ai_knowledge_folder (Id,KnowledgeBaseId,ParentId,Name,CreatedAtUtc,UpdatedAtUtc,Version) SELECT @Id,knowledge.Id,@ParentId,@Name,@Now,@Now,1 FROM fn_ai_knowledge_base AS knowledge WHERE knowledge.Id=@KnowledgeBaseId AND knowledge.OwnerUserId=@OwnerUserId AND knowledge.IsEnabled=1 AND (SELECT COUNT(*) FROM fn_ai_knowledge_folder WHERE KnowledgeBaseId=knowledge.Id)<500" + Host, SqlDataScope.HostOnly);
    internal static readonly SqlStatement InsertFolderTenant = new("ai.knowledge_directory.insert_folder_tenant", "INSERT INTO fn_ai_knowledge_folder (Id,KnowledgeBaseId,ParentId,Name,CreatedAtUtc,UpdatedAtUtc,Version) SELECT @Id,knowledge.Id,@ParentId,@Name,@Now,@Now,1 FROM fn_ai_knowledge_base AS knowledge WHERE knowledge.Id=@KnowledgeBaseId AND knowledge.OwnerUserId=@OwnerUserId AND knowledge.IsEnabled=1 AND (SELECT COUNT(*) FROM fn_ai_knowledge_folder WHERE KnowledgeBaseId=knowledge.Id)<500" + Tenant, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement UpdateFolderHost = new("ai.knowledge_directory.update_folder_host", "UPDATE fn_ai_knowledge_folder SET ParentId=@ParentId,Name=@Name,UpdatedAtUtc=@Now,Version=Version+1 WHERE Id=@Id AND Version=@Version AND EXISTS (SELECT 1 FROM fn_ai_knowledge_base AS knowledge WHERE knowledge.Id=@KnowledgeBaseId AND knowledge.Id=fn_ai_knowledge_folder.KnowledgeBaseId AND knowledge.OwnerUserId=@OwnerUserId AND knowledge.IsEnabled=1" + Host + ")", SqlDataScope.HostOnly);
    internal static readonly SqlStatement UpdateFolderTenant = new("ai.knowledge_directory.update_folder_tenant", "UPDATE fn_ai_knowledge_folder SET ParentId=@ParentId,Name=@Name,UpdatedAtUtc=@Now,Version=Version+1 WHERE Id=@Id AND Version=@Version AND EXISTS (SELECT 1 FROM fn_ai_knowledge_base AS knowledge WHERE knowledge.Id=@KnowledgeBaseId AND knowledge.Id=fn_ai_knowledge_folder.KnowledgeBaseId AND knowledge.OwnerUserId=@OwnerUserId AND knowledge.IsEnabled=1" + Tenant + ")", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement DeleteFolderHost = new("ai.knowledge_directory.delete_folder_host", "DELETE FROM fn_ai_knowledge_folder WHERE Id=@Id AND Version=@Version AND NOT EXISTS (SELECT 1 FROM fn_ai_knowledge_directory WHERE FolderId=@Id) AND EXISTS (SELECT 1 FROM fn_ai_knowledge_base AS knowledge WHERE knowledge.Id=@KnowledgeBaseId AND knowledge.Id=fn_ai_knowledge_folder.KnowledgeBaseId AND knowledge.OwnerUserId=@OwnerUserId AND knowledge.IsEnabled=1" + Host + ")", SqlDataScope.HostOnly);
    internal static readonly SqlStatement DeleteFolderTenant = new("ai.knowledge_directory.delete_folder_tenant", "DELETE FROM fn_ai_knowledge_folder WHERE Id=@Id AND Version=@Version AND NOT EXISTS (SELECT 1 FROM fn_ai_knowledge_directory WHERE FolderId=@Id) AND EXISTS (SELECT 1 FROM fn_ai_knowledge_base AS knowledge WHERE knowledge.Id=@KnowledgeBaseId AND knowledge.Id=fn_ai_knowledge_folder.KnowledgeBaseId AND knowledge.OwnerUserId=@OwnerUserId AND knowledge.IsEnabled=1" + Tenant + ")", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement InsertDirectoryHost = new("ai.knowledge_directory.insert_directory_host", "INSERT INTO fn_ai_knowledge_directory (Id,FolderId,TagsJson,ResponsibleUserId,LastRequestKey,RequestHash,UpdatedAtUtc,Version) SELECT document.Id,@FolderId,@TagsJson,@ResponsibleUserId,@RequestKey,@RequestHash,@Now,1 FROM fn_ai_knowledge_document AS document INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId WHERE document.Id=@DocumentId AND knowledge.Id=@KnowledgeBaseId AND document.IsDeleted=0 AND knowledge.OwnerUserId=@OwnerUserId AND knowledge.IsEnabled=1 AND NOT EXISTS (SELECT 1 FROM fn_ai_knowledge_directory WHERE Id=document.Id)" + Host, SqlDataScope.HostOnly);
    internal static readonly SqlStatement InsertDirectoryTenant = new("ai.knowledge_directory.insert_directory_tenant", "INSERT INTO fn_ai_knowledge_directory (Id,FolderId,TagsJson,ResponsibleUserId,LastRequestKey,RequestHash,UpdatedAtUtc,Version) SELECT document.Id,@FolderId,@TagsJson,@ResponsibleUserId,@RequestKey,@RequestHash,@Now,1 FROM fn_ai_knowledge_document AS document INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId WHERE document.Id=@DocumentId AND knowledge.Id=@KnowledgeBaseId AND document.IsDeleted=0 AND knowledge.OwnerUserId=@OwnerUserId AND knowledge.IsEnabled=1 AND NOT EXISTS (SELECT 1 FROM fn_ai_knowledge_directory WHERE Id=document.Id)" + Tenant, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement UpdateDirectoryHost = new("ai.knowledge_directory.update_directory_host", "UPDATE fn_ai_knowledge_directory SET FolderId=@FolderId,TagsJson=@TagsJson,ResponsibleUserId=@ResponsibleUserId,LastRequestKey=@RequestKey,RequestHash=@RequestHash,UpdatedAtUtc=@Now,Version=Version+1 WHERE Id=@DocumentId AND Version=@Version AND EXISTS (SELECT 1 FROM fn_ai_knowledge_document AS document INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId WHERE document.Id=@DocumentId AND knowledge.Id=@KnowledgeBaseId AND document.IsDeleted=0 AND knowledge.OwnerUserId=@OwnerUserId AND knowledge.IsEnabled=1" + Host + ")", SqlDataScope.HostOnly);
    internal static readonly SqlStatement UpdateDirectoryTenant = new("ai.knowledge_directory.update_directory_tenant", "UPDATE fn_ai_knowledge_directory SET FolderId=@FolderId,TagsJson=@TagsJson,ResponsibleUserId=@ResponsibleUserId,LastRequestKey=@RequestKey,RequestHash=@RequestHash,UpdatedAtUtc=@Now,Version=Version+1 WHERE Id=@DocumentId AND Version=@Version AND EXISTS (SELECT 1 FROM fn_ai_knowledge_document AS document INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId WHERE document.Id=@DocumentId AND knowledge.Id=@KnowledgeBaseId AND document.IsDeleted=0 AND knowledge.OwnerUserId=@OwnerUserId AND knowledge.IsEnabled=1" + Tenant + ")", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement ResponsibleHost = new("ai.knowledge_directory.responsible_host", "SELECT knowledge.Id FROM fn_ai_knowledge_base AS knowledge WHERE knowledge.Id=@KnowledgeBaseId AND knowledge.IsEnabled=1 AND (knowledge.OwnerUserId=@ResponsibleUserId OR EXISTS (SELECT 1 FROM fn_ai_knowledge_member AS member WHERE member.KnowledgeBaseId=knowledge.Id AND member.UserId=@ResponsibleUserId))" + Host, SqlDataScope.HostOnly);
    internal static readonly SqlStatement ResponsibleTenant = new("ai.knowledge_directory.responsible_tenant", "SELECT knowledge.Id FROM fn_ai_knowledge_base AS knowledge WHERE knowledge.Id=@KnowledgeBaseId AND knowledge.IsEnabled=1 AND (knowledge.OwnerUserId=@ResponsibleUserId OR EXISTS (SELECT 1 FROM fn_ai_knowledge_member AS member WHERE member.KnowledgeBaseId=knowledge.Id AND member.UserId=@ResponsibleUserId))" + Tenant, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private static string Lock(bool mysql, bool tenant) => "SELECT knowledge.Id" + (mysql ? OwnerRoot : OwnerRoot.Replace(" AS knowledge ", " AS knowledge WITH(UPDLOCK,HOLDLOCK) ", StringComparison.Ordinal)) + (tenant ? Tenant : Host) + (mysql ? " FOR UPDATE" : "");
    private static readonly SqlStatement LockSqlServerHost = new("ai.knowledge_directory.lock_sqlserver_host", Lock(false, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement LockSqlServerTenant = new("ai.knowledge_directory.lock_sqlserver_tenant", Lock(false, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private static readonly SqlStatement LockMySqlHost = new("ai.knowledge_directory.lock_mysql_host", Lock(true, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement LockMySqlTenant = new("ai.knowledge_directory.lock_mysql_tenant", Lock(true, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static SqlStatement LockFor(DatabaseProvider provider, bool scoped) => provider == DatabaseProvider.MySql ? scoped ? LockMySqlTenant : LockMySqlHost : scoped ? LockSqlServerTenant : LockSqlServerHost;
    private const string DirectoryRoot = " FROM fn_ai_knowledge_document AS document INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId LEFT JOIN fn_ai_knowledge_directory AS directory ON directory.Id=document.Id LEFT JOIN fn_ai_knowledge_publication_head AS head ON head.Id=document.Id LEFT JOIN fn_ai_knowledge_publication AS publication ON publication.Id=head.PublicationId AND publication.DocumentId=document.Id LEFT JOIN fn_ai_knowledge_active_generation AS candidate ON candidate.DocumentId=document.Id WHERE knowledge.Id=@KnowledgeBaseId AND document.IsDeleted=0 AND knowledge.IsEnabled=1";
    private static string Filter(bool mysql, bool scoped) => DirectoryRoot + (scoped ? Tenant : Host) + " AND " + (mysql ? AiKnowledgeReadSql.LayersMySql : AiKnowledgeReadSql.Layers)
        + " AND (@FolderId IS NULL OR directory.FolderId=@FolderId) AND (@ResponsibleUserId IS NULL OR directory.ResponsibleUserId=@ResponsibleUserId)"
        + " AND (@Tag IS NULL OR EXISTS (SELECT 1 FROM " + (mysql ? "JSON_TABLE(directory.TagsJson,'$[*]' COLUMNS (Tag varchar(64) PATH '$')) AS tags WHERE CAST(tags.Tag AS BINARY)=CAST(@Tag AS BINARY)" : "OPENJSON(directory.TagsJson) WITH (Tag nvarchar(64) '$') AS tags WHERE CONVERT(varbinary(max),tags.Tag)=CONVERT(varbinary(max),CONVERT(nvarchar(64),@Tag))") + "))";
    private static string State(bool mysql) => "CASE WHEN head.PublicationId IS NULL THEN 'draft' WHEN publication.EffectiveToUtc<=" + (mysql ? "UTC_TIMESTAMP(6)" : "SYSUTCDATETIME()") + " THEN 'expired' WHEN publication.EffectiveFromUtc>" + (mysql ? "UTC_TIMESTAMP(6)" : "SYSUTCDATETIME()") + " THEN 'scheduled' ELSE 'published' END";
    private static string Columns(bool mysql) => "document.Id,document.Title,directory.FolderId,COALESCE(directory.TagsJson,'[]') AS TagsJson,directory.ResponsibleUserId,COALESCE(directory.Version,0) AS Version,directory.LastRequestKey,directory.RequestHash,document.Version AS DocumentVersion," + State(mysql) + " AS PublicationState,head.PublicationId,COALESCE(head.Version,0) AS HeadVersion,candidate.VersionId AS CandidateVersionId,(SELECT " + (mysql ? "" : "TOP (1) ") + "pending.Id FROM fn_ai_knowledge_publication AS pending WHERE pending.DocumentId=document.Id AND pending.StateKey IN ('pending','approved') ORDER BY pending.CreatedAtUtc DESC,pending.Id DESC" + (mysql ? " LIMIT 1" : "") + ") AS PendingPublicationId";
    private static string Page(bool mysql, bool scoped) => "SELECT " + Columns(mysql) + Filter(mysql, scoped) + " AND (@State IS NULL OR " + State(mysql) + "=@State) ORDER BY document.CreatedAtUtc,document.Id " + (mysql ? "LIMIT @PageSize OFFSET @Offset" : "OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY");
    private static string Count(bool mysql, bool scoped) => "SELECT COUNT(*)" + Filter(mysql, scoped) + " AND (@State IS NULL OR " + State(mysql) + "=@State)";
    private static string Item(bool mysql, bool scoped) => "SELECT " + Columns(mysql) + Filter(mysql, scoped) + " AND document.Id=@DocumentId";
    private static readonly SqlStatement PageSqlServerHost = new("ai.knowledge_directory.page_sqlserver_host", Page(false, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement PageSqlServerTenant = new("ai.knowledge_directory.page_sqlserver_tenant", Page(false, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private static readonly SqlStatement PageMySqlHost = new("ai.knowledge_directory.page_mysql_host", Page(true, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement PageMySqlTenant = new("ai.knowledge_directory.page_mysql_tenant", Page(true, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private static readonly SqlStatement CountSqlServerHost = new("ai.knowledge_directory.count_sqlserver_host", Count(false, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement CountSqlServerTenant = new("ai.knowledge_directory.count_sqlserver_tenant", Count(false, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private static readonly SqlStatement CountMySqlHost = new("ai.knowledge_directory.count_mysql_host", Count(true, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement CountMySqlTenant = new("ai.knowledge_directory.count_mysql_tenant", Count(true, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private static readonly SqlStatement ItemSqlServerHost = new("ai.knowledge_directory.item_sqlserver_host", Item(false, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement ItemSqlServerTenant = new("ai.knowledge_directory.item_sqlserver_tenant", Item(false, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private static readonly SqlStatement ItemMySqlHost = new("ai.knowledge_directory.item_mysql_host", Item(true, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement ItemMySqlTenant = new("ai.knowledge_directory.item_mysql_tenant", Item(true, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static SqlStatement PageFor(DatabaseProvider provider, bool scoped) => provider == DatabaseProvider.MySql ? scoped ? PageMySqlTenant : PageMySqlHost : scoped ? PageSqlServerTenant : PageSqlServerHost;
    internal static SqlStatement CountFor(DatabaseProvider provider, bool scoped) => provider == DatabaseProvider.MySql ? scoped ? CountMySqlTenant : CountMySqlHost : scoped ? CountSqlServerTenant : CountSqlServerHost;
    internal static SqlStatement ItemFor(DatabaseProvider provider, bool scoped) => provider == DatabaseProvider.MySql ? scoped ? ItemMySqlTenant : ItemMySqlHost : scoped ? ItemSqlServerTenant : ItemSqlServerHost;
    private static readonly SqlStatement BoundedFoldersSqlServerHost = new("ai.knowledge_directory.bounded_folders_sqlserver_host", "SELECT TOP (501) " + FolderColumns + FolderRoot + Host + FolderAccess(false, false) + " ORDER BY folder.Id", SqlDataScope.HostOnly);
    private static readonly SqlStatement BoundedFoldersSqlServerTenant = new("ai.knowledge_directory.bounded_folders_sqlserver_tenant", "SELECT TOP (501) " + FolderColumns + FolderRoot + Tenant + FolderAccess(false, true) + " ORDER BY folder.Id", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private static readonly SqlStatement BoundedFoldersMySqlHost = new("ai.knowledge_directory.bounded_folders_mysql_host", "SELECT " + FolderColumns + FolderRoot + Host + FolderAccess(true, false) + " ORDER BY folder.Id LIMIT 501", SqlDataScope.HostOnly);
    private static readonly SqlStatement BoundedFoldersMySqlTenant = new("ai.knowledge_directory.bounded_folders_mysql_tenant", "SELECT " + FolderColumns + FolderRoot + Tenant + FolderAccess(true, true) + " ORDER BY folder.Id LIMIT 501", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static SqlStatement FoldersFor(DatabaseProvider provider, bool scoped) => provider == DatabaseProvider.MySql ? scoped ? BoundedFoldersMySqlTenant : BoundedFoldersMySqlHost : scoped ? BoundedFoldersSqlServerTenant : BoundedFoldersSqlServerHost;
}
